# Helper: reverse complement
sub rev_comp {
    my ($s) = @_;
    my $rc = reverse($s);
    $rc =~ tr/ATGC/TACG/;
    return $rc;
}

# Helper: calculate Tm (direct command, no piping)
sub calc_tm {
    my ($oligo) = @_;
    return -1 if length($oligo) < 2 || length($oligo) > 36;
    my $result = `oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $oligo 2>/dev/null`;
    chomp $result;
    return ($result =~ /^[\d.]+$/) ? $result + 0 : -1;
}

# BsaI-HF v2 site: GGTCTC with N^(NNNN) overhang (cuts within recognition)
# We add the site + overhang bases before primer annealing region

# For Golden Gate assembly, we need to design overhangs that create
# compatible sticky ends between fragments in the correct orientation

# Strategy:
# - For each template (input, egfp, flag, snap), design fwd and rev primers
# - Forward primer: BsaI site + overhang (4bp) + annealing region from start
# - Reverse primer: BsaI site + overhang (4bp) + annealing region from end
# - Each template gets unique overhangs that match in the correct assembly order

# Assembly order should be: input -> egfp -> flag -> snap -> back to input

# Define overhangs for each junction (4bp sticky ends)
# These are examples - need to design based on BsaI cutting
my %overhangs = (
    'input_fwd' => 'TACA',
    'input_rev' => 'GTAC',
    'egfp_fwd' => 'GTAC',
    'egfp_rev' => 'ATAT',
    'flag_fwd' => 'ATAT',
    'flag_rev' => 'CGCG',
    'snap_fwd' => 'CGCG',
    'snap_rev' => 'TACA',
};

my @templates = ('input', 'egfp', 'flag', 'snap');
my @primers;

foreach my $template (@templates) {
    my $seq = $sequences{$template};

    print "=== $template ===\n";
    print "Length: " . length($seq) . " bp\n";

    # Forward primer: from start of sequence
    my $fwd_annealing_len = 25;  # Start with 25bp annealing region
    while ($fwd_annealing_len >= 15 && $fwd_annealing_len <= 45) {
        my $fwd_annealing = substr($seq, 0, $fwd_annealing_len);
        my $fwd_overhang = $overhangs{$template . '_fwd'};
        my $fwd_full = $fwd_overhang . $fwd_annealing;

        my $fwd_tm = calc_tm($fwd_annealing);
        print "FWD attempt ($fwd_annealing_len bp annealing): Tm = $fwd_tm\n";

        if ($fwd_tm >= 58 && $fwd_tm <= 72) {
            # Found good forward primer
            push @primers, {
                name => "${template}_fwd",
                full_seq => 'GGTCTC' . $fwd_full,
                annealing => $fwd_annealing,
                tm => $fwd_tm,
                dir => 'fwd'
            };
            print "  -> Selected FWD\n";
            last;
        }
        $fwd_annealing_len++;
    }

    # Reverse primer: from end of sequence
    my $rev_annealing_len = 25;
    while ($rev_annealing_len >= 15 && $rev_annealing_len <= 45) {
        my $rev_annealing_raw = substr($seq, -$rev_annealing_len);
        my $rev_annealing = rev_comp($rev_annealing_raw);
        my $rev_overhang = $overhangs{$template . '_rev'};
        my $rev_full = $rev_overhang . $rev_annealing;

        my $rev_tm = calc_tm($rev_annealing);
        print "REV attempt ($rev_annealing_len bp annealing): Tm = $rev_tm\n";

        if ($rev_tm >= 58 && $rev_tm <= 72) {
            # Found good reverse primer
            push @primers, {
                name => "${template}_rev",
                full_seq => 'GGTCTC' . $rev_full,
                annealing => $rev_annealing,
                tm => $rev_tm,
                dir => 'rev'
            };
            print "  -> Selected REV\n";
            last;
        }
        $rev_annealing_len++;
    }
    print "\n";
}

print "Summary of designed primers:\n";
foreach my $p (@primers) {
    print "$p->{name}: Tm=$p->{tm}, annealing=" . length($p->{annealing}) . "bp\n";
}

